using System.Reflection;
using System.Runtime.Loader;
using System.Text.Json;
string binaries = Path.GetFullPath(args[0]);
string output = Path.GetFullPath(args[1]); Directory.CreateDirectory(output);
AssemblyLoadContext.Default.Resolving += (context, name) => File.Exists(Path.Combine(binaries, name.Name + ".dll")) ? context.LoadFromAssemblyPath(Path.Combine(binaries, name.Name + ".dll")) : null;
var tests = AssemblyLoadContext.Default.LoadFromAssemblyPath(Path.Combine(binaries, "Hexalith.EventStore.Server.Tests.dll"));
var fixtureType = tests.GetType("Hexalith.EventStore.Server.Tests.Security.DeletionConsumptionFixture", true)!;
foreach (bool consumed in new[] { false, true })
{
    object fixture = Activator.CreateInstance(fixtureType, nonPublic: true)!;
    fixtureType.GetProperty("LoseResponse", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(fixture, !consumed);
    object request = fixtureType.GetMethod("Request", BindingFlags.Static | BindingFlags.NonPublic)!.Invoke(null, new object[] { "batch-1", "key-v1", 1L, null })!;
    request.GetType().GetProperty("DetachedJws")!.SetValue(request, "exact-protected-header..exact-detached-signature");
    object actor = fixtureType.GetProperty("Actor", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(fixture)!;
    async Task<object> Invoke(string method, params object[] parameters)
    {
        var task = (Task)actor.GetType().GetMethod(method)!.Invoke(actor, parameters)!; await task;
        return task.GetType().GetProperty("Result")!.GetValue(task)!;
    }
    await Invoke("RegisterAsync", request);
    object outcome = await Invoke("ReserveAndConsumeAsync", request);
    object receipt = outcome.GetType().GetProperty("ReceiptId")!.GetValue(outcome)!;
    object result = await Invoke("ReadReservedManifestOriginalAsync", "tenant-a", "batch-1", receipt);
    File.WriteAllText(Path.Combine(output, consumed ? "consumed.json" : "reserved.json"), JsonSerializer.Serialize(result, result.GetType()) + "\n");
}
